import * as React from "react";
import { cn } from "@/lib/utils";

export interface TabsProps extends React.HTMLAttributes<HTMLDivElement> {
  items?: string[];
  activeIndex?: number;
  onChange?: (index: number) => void;
  animationType?: 'crawl-slide' | 'spring-elastic' | 'glow-fade';
  inkColor?: string;
}

export const Tabs: React.FC<TabsProps> = ({ items = ['Overview', 'Zine Press', 'Halftones'], activeIndex = 0, onChange, className, ...props }) => {
  return (
    <div className={cn("inline-flex p-1 bg-black/5 rounded-xl font-mono text-xs", className)} {...props}>
      {items.map((item, idx) => (
        <button key={idx} onClick={() => onChange?.(idx)} className={cn("px-4 py-2 rounded-lg font-bold transition-all", idx === activeIndex ? "bg-white text-black shadow-xs" : "opacity-70 hover:opacity-100")}>
          {item}
        </button>
      ))}
    </div>
  );
};
